                support_color = grid[r][col]
                break

        if support_color is None:
            continue  # No marker support

        # Find cap_boundary: going up from support_row, stop at first non-0 != support_color
        cap_boundary = support_row + 1
        for r in range(support_row, -1, -1):
            v = grid[r][col]
            if v != 0 and v != support_color:
                cap_boundary = r + 1
                break

        # Find cap_fill_color: first non-zero going UP from cap_boundary (exclusive, i.e., starting at cap_boundary-1)
        cap_fill_color = None
        for r in range(cap_boundary - 1, -1, -1):
            v = grid[r][col]
            if v != 0:
                cap_fill_color = v
                break

        # Fill support color from cap_boundary down to support_row
        for r in range(cap_boundary, support_row + 1):
