        if cap_fill_color is None:
            cap_fill_color = 0
        for r in range(cap_boundary):
            output[r][col] = cap_fill_color

        # Marker fills from marker_row down to bottom
        for r in range(marker_row + 1, n):
            output[r][col] = 5

    return output

